generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?cashFlowType (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
WHERE {
  {
    SELECT DISTINCT ?investor ?riskTolerance ?cashFlowType
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:hasCashFlowType ?cashFlowType .
    }
  }
  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:progressPct ?progressPct .
}
GROUP BY ?riskTolerance ?cashFlowType

